INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1, 2, "2025/01/31 12:00:00", "カリン", 3.414, 1, 0.0, 62, -416.5, 1, 1000001, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", 1, 2, "2025/01/31 12:00:00", "カリン", 3.099, 2, 0.0, 62, -416.5, 1, 1000002, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", 1, 2, "2025/01/31 12:00:00", "カリン", 2.801, 3, 0.0, 63, -416.5, 1, 1000003, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", 1, 2, "2025/01/31 12:00:00", "カリン", 0.0, 4, 0.0, 63, -416.5, 2, 1000004, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 1, "2025/01/31 12:00:00", "カリン", 2.12, 5, 0.0, 64, -363.0, 2, 1000005, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1, 2, "2025/01/31 12:00:00", "カリン", 1.68, 6, 0.0, 64, -363.0, 1, 1000006, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 1, "2025/01/31 12:00:00", "カリン", 2.33, 7, 0.0, 64, -363.0, 2, 1000007, 190801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 10201, 7, "2025/01/31 12:00:00", "ラビリスタ", 5.18, 101, -6.0, 61, -285.0, 3, 1020101, 133701);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 10201, 2, "2025/01/31 12:00:00", "クリスティーナ", 8.77, 201, -2.0, 61, -285.0, 1, 1020102, 133901);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 10201, 1, "2025/01/31 12:00:00", "ネネカ", 15.5, 301, 0.0, 61, -285.0, 6, 1020103, 133801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 10202, 5, "2025/02/28 12:00:00", "ランファ", 9.061, 101, 0.0, 61, -285.0, 2, 1020201, 134301);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 10202, 2, "2025/02/28 12:00:00", "チカ", 7.699, 201, 0.0, 61, -285.0, 1, 1020202, 134401);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 10203, 2, "2025/03/31 12:00:00", "アオイ", 8.595, 101, 0.0, 61, -285.0, 1, 1020301, 134601);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 10203, 2, "2025/03/31 12:00:00", "クローチェ", 7.758, 201, 0.0, 61, -285.0, 1, 1020302, 134501);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 10204, 6, "2025/04/30 12:00:00", "ルイズマリー", 7.0, 101, 0.0, 61, -285.0, 2, 1020401, 132302);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 10204, 2, "2025/04/30 12:00:00", "イロハ", 7.904, 201, 0.0, 61, -285.0, 1, 1020402, 132402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 10204, 2, "2025/04/30 12:00:00", "ソノ", 8.487, 301, 0.0, 61, -285.0, 4, 1020403, 132502);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 10205, 2, "2025/05/31 12:00:00", "カノン", 8.763, 101, 0.0, 61, -285.0, 1, 1020502, 134901);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 10205, 3, "2025/05/31 12:00:00", "ツムギ", 6.417, 201, 0.0, 61, -285.0, 1, 1020503, 134801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10206, 7, "2025/06/30 12:00:00", "エリス", 10.335, 101, 0.0, 61, -285.0, 3, 1020601, 135001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 10206, 4, "2025/06/30 12:00:00", "シェフィ", 6.281, 201, 0.0, 61, -285.0, 2, 1020602, 135101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 10206, 2, "2025/06/30 12:00:00", "プレシア", 12.244, 301, 0.0, 61, -285.0, 1, 1020603, 135201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 10207, 8, "2025/07/31 12:00:00", "クリア", 6.339, 101, 0.0, 61, -285.0, 2, 1020701, 135301);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 10207, 9, "2025/07/31 12:00:00", "アネモネ", 8.184, 201, 0.0, 61, -285.0, 7, 1020702, 135401);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 10208, 2, "2025/08/31 12:00:00", "アイラ", 3.906, 101, 0.0, 61, -285.0, 9, 1020801, 129101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 10208, 2, "2025/08/31 12:00:00", "シナツ", 14.465, 201, 0.0, 61, -285.0, 1, 1020802, 129201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 10208, 3, "2025/08/31 12:00:00", "ヒヨリ", 8.662, 301, 0.0, 61, -285.0, 4, 1020803, 100101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10208, 3, "2025/08/31 12:00:00", "レイ", 10.915, 401, 0.0, 61, -285.0, 1, 1020804, 100301);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 10209, 7, "2025/09/30 12:00:00", "ユキノ", 6.042, 101, 0.0, 61, -285.0, 1, 1020901, 135802);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 10209, 1, "2025/09/30 12:00:00", "サツキ", 9.402, 201, 0.0, 61, -285.0, 4, 1020902, 135903);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 10209, 1, "2025/09/30 12:00:00", "ルルィ", 8.16, 301, 0.0, 61, -285.0, 8, 1020903, 136902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 10210, 2, "2025/10/31 12:00:00", "カスミ", 5.0, 101, 0.0, 61, -285.0, 3, 1021001, 137401);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 10210, 1, "2025/10/31 12:00:00", "アラクネ", 8.12, 201, 0.0, 61, -285.0, 4, 1021002, 136001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 10210, 2, "2025/10/31 12:00:00", "ナーナ", 6.386, 301, 0.0, 61, -285.0, 4, 1021003, 136202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 10211, 4, "2025/11/30 12:00:00", "ユイ", 7.438, 101, 0.0, 61, -285.0, 3, 1021101, 136402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 10211, 5, "2025/11/30 12:00:00", "ミソラ", 8.35, 201, 0.0, 61, -285.0, 1, 1021102, 136302);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 10212, 2, "2025/12/31 12:00:00", "シズル", 5.0, 101, 0.0, 61, -285.0, 1, 1021201, 136501);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 10212, 2, "2025/12/31 12:00:00", "リノ", 5.25, 201, 0.0, 61, -285.0, 1, 1021202, 137902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 10212, 2, "2025/12/31 12:00:00", "ラビリスタ", 7.5, 301, 0.0, 61, -285.0, 1, 1021203, 106801);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 10213, 2, "2026/01/31 12:00:00", "ライラエル", 8.204, 101, 0.0, 61, -285.0, 1, 1021301, 126501);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 10213, 2, "2026/01/31 12:00:00", "ネフィ＝ネラ", 7.176, 201, 0.0, 61, -285.0, 1, 1021302, 129701);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 10213, 5, "2026/01/31 12:00:00", "ヴァイオレット", 8.602, 301, 0.0, 61, -285.0, 1, 1021303, 133101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10213, 3, "2026/02/06 12:00:00", "ライラエル", 10.14, 102, 0.0, 61, -285.0, 1, 1021304, 138101);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10213, 7, "2026/02/06 12:00:00", "ネフィ＝ネラ", 10.152, 202, 0.0, 61, -285.0, 1, 1021305, 138201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 10213, 3, "2026/02/06 12:00:00", "ヴァイオレット", 9.688, 302, 0.0, 61, -285.0, 4, 1021306, 138001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 10213, 1, "2026/02/12 12:00:00", "ペコリーヌ", 5.928, 401, 0.0, 61, -285.0, 2, 1021307, 138301);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 10214, 2, "2026/02/28 12:00:00", "ワカナ", 9.19, 101, 0.0, 61, -285.0, 4, 1021401, 138702);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 10214, 3, "2026/02/28 12:00:00", "シオリ", 8.724, 201, 0.0, 61, -285.0, 1, 1021402, 138802);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 10215, 1, "2026/03/31 12:00:00", "グレイス", 7.758, 101, 0.0, 61, -285.0, 4, 1021501, 138902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 10215, 4, "2026/03/31 12:00:00", "キョウカ", 6.375, 201, 0.0, 61, -285.0, 6, 1021502, 139002);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 10215, 1, "2026/03/31 12:00:00", "ルルィ", 6.173, 301, 0.0, 61, -285.0, 6, 1021503, 136902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 10216, 2, "2026/04/30 12:00:00", "ミホ", 4.202, 101, 0.0, 61, -285.0, 6, 1021601, 139202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 10216, 1, "2026/04/30 12:00:00", "マホ", 2.842, 201, 0.0, 61, -285.0, 6, 1021602, 139302);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 10216, 1, "2026/04/30 12:00:00", "エリカ", 4.598, 301, 0.0, 61, -285.0, 4, 1021603, 139402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 10217, 3, "2026/05/31 12:00:00", "リリ", 6.533, 101, 0.0, 61, -285.0, 4, 1021701, 125802);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 10217, 3, "2026/05/31 12:00:00", "プレシア", 5.0, 301, 0.0, 61, -285.0, 3, 1021702, 126102);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 10217, 4, "2026/05/31 12:00:00", "クリア", 5.214, 201, 0.0, 61, -285.0, 3, 1021703, 126002);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 10217, 3, "2026/05/31 12:00:00", "リリ", 8.781, 102, 0.0, 61, -285.0, 1, 1021704, 139501);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 10217, 1, "2026/05/31 12:00:00", "クリア", 6.529, 202, 0.0, 61, -285.0, 2, 1021705, 139601);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 10217, 2, "2026/05/31 12:00:00", "プレシア", 3.195, 302, 0.0, 61, -285.0, 3, 1021706, 139701);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 10218, 3, "2026/06/30 12:00:00", "ルイズマリー", 12.43, 101, 0.0, 61, -285.0, 2, 1021801, 139902);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 10218, 3, "2026/06/30 12:00:00", "クレジッタ", 6.35, 201, 0.0, 61, -285.0, 2, 1021802, 140001);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10219, 5, "2026/07/31 12:00:00", "フブキ", 10.23, 101, 0.0, 61, -285.0, 1, 1021901, 140102);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 10219, 2, "2026/07/31 12:00:00", "ヴァンピィ", 5.584, 201, 0.0, 61, -285.0, 1, 1021902, 140201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 10220, 3, "2026/08/31 12:00:00", "クローチェ", 2.8, 201, 0.0, 61, -285.0, 6, 1022001, 126401);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 10220, 3, "2026/08/31 12:00:00", "ヴルム", 8.9, 101, 0.0, 61, -285.0, 4, 1022002, 127802);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 10220, 1, "2026/08/31 12:00:00", "クローチェ", 4.49, 202, 0.0, 61, -285.0, 2, 1022003, 140602);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 10220, 3, "2026/08/31 12:00:00", "ヴルム", 9.42, 102, 0.0, 61, -285.0, 1, 1022004, 140501);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 10220, 1, "2026/08/31 12:00:00", "リーザ", 7.0, 301, 0.0, 61, -285.0, 4, 1022005, 140402);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 2, "2026/04/10 12:00:00", "カリン", 3.414, 1, 0.0, 62, -416.5, 1, 2000001, 190805);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 2, "2026/04/10 12:00:00", "カリン", 3.099, 2, 0.0, 62, -416.5, 1, 2000002, 190805);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 2, "2026/04/10 12:00:00", "カリン", 2.801, 3, 0.0, 63, -416.5, 1, 2000003, 190805);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "報酬がもらえますよ！\nチェックしてみてください", 2, 2, "2026/04/10 12:00:00", "カリン", 0.0, 4, 0.0, 63, -416.5, 2, 2000004, 190805);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2, 1, "2026/04/10 12:00:00", "カリン", 2.12, 5, 0.0, 64, -363.0, 2, 2000005, 190805);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 2, "2026/04/10 12:00:00", "カリン", 1.68, 6, 0.0, 64, -363.0, 1, 2000006, 190805);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES ("2030/01/01 14:59:59", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2, 1, "2026/04/10 12:00:00", "カリン", 2.33, 7, 0.0, 64, -363.0, 2, 2000007, 190805);
